// Allowance for DNS rows that reach the workspace late; set from the live test's measurement
let ingestion_delay = 30m;
// Equals queryFrequency: each run evaluates the rows ingested since the previous run
let rule_lookback = 1h;
// Feed rows ingested within this period are considered; cannot exceed queryPeriod
let nrd_lookback = 14d;
// A domain this rule alerted on is not alerted on again for this long
let dedupe_lookback = 7d;
// Lookups from at least this many hosts are probably infrastructure: severity drops to Low
let estate_wide_hosts = 20;
let Allowlisted = union
    (_GetWatchlist('WhoisXMLDomainAllowlist') | project Domain = tolower(tostring(SearchKey))),
    (_GetWatchlist('WhoisXMLDomainAllowlistCustom') | project Domain = tolower(tostring(SearchKey)));
// Domains this rule already alerted on (custom details WxaRule and WxaDomain)
let AlreadyAlerted = SecurityAlert
    | where TimeGenerated >= ago(dedupe_lookback)
    | where ProviderName == "ASI Scheduled Alerts"
    | extend Details = todynamic(tostring(todynamic(ExtendedProperties)["Custom Details"]))
    | where tostring(Details.WxaRule[0]) == "R1"
    | project Domain = tostring(Details.WxaDomain[0]);
// The hour's lookups, read twice: once for every queried name, then again for the clients of the names that matched
let DnsRows = _Im_Dns(starttime=ago(ingestion_delay + rule_lookback))
    | where isnotempty(DnsQuery)
    | where coalesce(ingestion_time(), TimeGenerated) > ago(rule_lookback)
    | extend Fqdn = tolower(trim_end(@"\.", DnsQuery));
// One row per queried name with only its time span and count, summarised before materialize: per-client detail
// for every name would exhaust the query's memory in estates that query millions of names an hour
let DnsByName = materialize(
    DnsRows
    | summarize
        StartTime = min(TimeGenerated),
        EndTime = max(TimeGenerated),
        Queries = count()
        by Fqdn
    | extend Labels = split(Fqdn, ".")
    | extend LabelCount = array_length(Labels)
    | extend Cand2 = iff(LabelCount >= 2, strcat(tostring(Labels[LabelCount - 2]), ".", tostring(Labels[LabelCount - 1])), "")
    | extend Cand3 = iff(LabelCount >= 3, strcat(tostring(Labels[LabelCount - 3]), ".", Cand2), "")
    | project-away Labels, LabelCount
);
let Candidates = union
    (DnsByName | where isnotempty(Cand2) | distinct Domain = Cand2),
    (DnsByName | where isnotempty(Cand3) | distinct Domain = Cand3)
    | distinct Domain;
// `in` considers at most 1,000,000 distinct values; above 900,000 candidates use a shuffle join instead
let NCand = toscalar(Candidates | count);
let Listed = WhoisXMLNRD_CL
    | where TimeGenerated >= ago(nrd_lookback)
    | where Reason == "added";
let NewDomains = union
        (Listed | where NCand <= 900000 | where DomainName in (Candidates)),
        (Listed | where NCand > 900000 | join kind=leftsemi hint.shufflekey=DomainName (Candidates | project DomainName = Domain) on DomainName)
    | where DomainName !in (AlreadyAlerted)
    // Allowlisted domains drop out through an anti-join from the small side: an in() filter fails above 1,000,000
    // values, which an imported list can reach
    | join kind=leftanti Allowlisted on $left.DomainName == $right.Domain
    // TimeGenerated is when the row reached this workspace; FeedDate is the data day of the WXA file
    | summarize ListedInWorkspace = min(TimeGenerated), FeedDate = max(FeedDate) by DomainName;
let Matched = materialize(
    NewDomains
    | join kind=inner (
        DnsByName
        | extend Candidate = pack_array(Cand2, Cand3)
        | mv-expand Candidate to typeof(string)
        | where isnotempty(Candidate)
    ) on $left.DomainName == $right.Candidate
);
let MatchedNames = Matched | distinct Fqdn;
// Clients only for the names that matched, joined from the small side: an in() filter fails above 1,000,000
// values, which one domain used for DNS tunnelling can reach
let ClientsByName = MatchedNames
    | join kind=rightsemi DnsRows on Fqdn
    // Windows DNS and most other sources leave SrcHostname empty; the client's IP address stands in for it
    | extend SrcClient = coalesce(column_ifexists("SrcHostname", ""), column_ifexists("SrcIpAddr", ""))
    | summarize
        HostHll = hll_if(SrcClient, isnotempty(SrcClient)),
        SourceIps = make_set(column_ifexists("SrcIpAddr", ""), 20),
        SourceHosts = make_set_if(SrcClient, isnotempty(SrcClient), 20),
        ReportedBy = make_set(column_ifexists("EventProduct", ""), 5)
        by Fqdn;
Matched
| join kind=inner ClientsByName on Fqdn
| summarize
    StartTime = min(StartTime),
    EndTime = max(EndTime),
    QueryCount = sum(Queries),
    HostHll = hll_merge(HostHll),
    SampleFqdns = make_set(Fqdn, 10),
    arg_max(Queries, SourceIps, SourceHosts, ReportedBy)
    by DomainName, FeedDate, ListedInWorkspace
| extend HostCount = dcount_hll(HostHll)
| extend
    SourceIp = tostring(SourceIps[0]),
    SourceHost = tostring(SourceHosts[0]),
    AlertSeverity = iff(HostCount >= estate_wide_hosts, "Low", "Medium"),
    WxaRule = "R1"
| project-away HostHll, Queries

let ingestion_delay = 30m;
let rule_lookback = 1h;
// Every active indicator is re-sent at least every 10 days, so 14 days holds the full active set
let ti_lookback = 14d;
let high_types = dynamic(["c2", "malware", "phishing", "botnet"]);
// Severity by recency; LastSeen in the table can trail the real last observation by up to 10 days
let recent = 14d;
let aging = 30d;
// Listings under a registered domain ranked in the top 100,000 are informational only, unless it is a hosting platform
let popular_rank = 100000;
let Allowlisted = union
    (_GetWatchlist('WhoisXMLDomainAllowlist') | project Domain = tolower(tostring(SearchKey))),
    (_GetWatchlist('WhoisXMLDomainAllowlistCustom') | project Domain = tolower(tostring(SearchKey)))
    | where isnotempty(Domain);
// Hosting platforms (free website hosts, site builders, dynamic DNS), where each subdomain is a different party's site
let HostingPlatformList = union
    (_GetWatchlist('WhoisXMLHostingPlatforms') | project Domain = trim_end(@"\.", trim(@"\s+", tolower(tostring(SearchKey))))),
    (_GetWatchlist('WhoisXMLHostingPlatformsCustom') | project Domain = trim_end(@"\.", trim(@"\s+", tolower(tostring(SearchKey)))))
    | where isnotempty(Domain);
// At most 100,000 platforms, well inside the 1,000,000 values an in() filter allows
let HostingPlatforms = toscalar(HostingPlatformList | summarize make_set(Domain, 100000));
// The hour's lookups, read twice: once for every queried name, then again for the clients of the names that matched
let DnsRows = _Im_Dns(starttime=ago(ingestion_delay + rule_lookback))
    | where isnotempty(DnsQuery)
    | where coalesce(ingestion_time(), TimeGenerated) > ago(rule_lookback)
    | extend Fqdn = tolower(trim_end(@"\.", DnsQuery));
// One row per queried name with only its time span and count, summarised before materialize: per-client detail
// for every name would exhaust the query's memory in estates that query millions of names an hour
let DnsByName = materialize(
    DnsRows
    | summarize
        StartTime = min(TimeGenerated),
        EndTime = max(TimeGenerated),
        Queries = count()
        by Fqdn
    | extend Labels = split(Fqdn, ".")
    | extend LabelCount = array_length(Labels)
    | extend Cand2 = iff(LabelCount >= 2, strcat(tostring(Labels[LabelCount - 2]), ".", tostring(Labels[LabelCount - 1])), "")
    | extend Cand3 = iff(LabelCount >= 3, strcat(tostring(Labels[LabelCount - 3]), ".", Cand2), "")
    | project-away Labels, LabelCount
);
// Registered-domain candidates only (last two and three labels), which bounds the list
let Candidates = union
    (DnsByName | where isnotempty(Cand2) | distinct Domain = Cand2),
    (DnsByName | where isnotempty(Cand3) | distinct Domain = Cand3)
    | distinct Domain;
let NCand = toscalar(Candidates | count);
// A listed host with three or more labels is reached through its last three labels
let Feed = WhoisXMLThreatDomains_CL
    | where TimeGenerated >= ago(ti_lookback)
    | extend FLabels = split(DomainName, ".")
    | extend FCount = array_length(FLabels)
    | extend F2 = iff(FCount >= 2, strcat(tostring(FLabels[FCount - 2]), ".", tostring(FLabels[FCount - 1])), "")
    | extend F3 = iff(FCount >= 3, strcat(tostring(FLabels[FCount - 3]), ".", tostring(FLabels[FCount - 2]), ".", tostring(FLabels[FCount - 1])), "")
    | project-away FLabels, FCount;
let ActiveThreats = materialize(
    union
        (Feed | where NCand <= 900000 | where DomainName in (Candidates) or F3 in (Candidates)),
        (Feed | where NCand > 900000
            | extend Key = pack_array(DomainName, F3)
            | mv-expand Key to typeof(string)
            | join kind=inner hint.shufflekey=Key (Candidates | project Key = Domain) on Key
            | project-away Key, Key1)
    // An allowlisted registered domain also covers every host listed under it. One anti-join from the small side per
    // name (the listing, its last two labels, its last three): an in() filter fails above 1,000,000 values
    | join kind=leftanti Allowlisted on $left.DomainName == $right.Domain
    | join kind=leftanti Allowlisted on $left.F2 == $right.Domain
    | join kind=leftanti Allowlisted on $left.F3 == $right.Domain
    // A listing under a hosting platform (its last two to four labels, the most specific entry first) is a different
    // party's site and keeps its severity; the platform itself and its own www host (www.weebly.com) do not
    | extend Labels = split(DomainName, ".")
    | extend F4 = iff(array_length(Labels) >= 4, strcat(tostring(Labels[array_length(Labels) - 4]), ".", F3), "")
    | extend Platform = iff(F4 in (HostingPlatforms), F4, iff(F3 in (HostingPlatforms), F3, iff(F2 in (HostingPlatforms), F2, "")))
    | extend OwnHost = array_length(Labels) == array_length(split(Platform, ".")) + 1 and tostring(Labels[0]) == "www"
    | extend Hosted = isnotempty(Platform) and DomainName != Platform and not(OwnHost)
    | project-away Labels, F4
    // Latest state per indicator: newest file date, then newest version of that file
    | extend StateKey = FeedDate + FeedVersion * 1s
    | summarize arg_max(StateKey, ChangeType, FirstSeen, LastSeen, ParentRank, IsPublicSuffix, Hosted) by DomainName, ThreatType
    | where ChangeType != "removed"
    | summarize
        ThreatTypes = make_set(ThreatType, 10),
        FeedFirstSeen = min(FirstSeen),
        FeedLastSeen = max(LastSeen),
        ParentRank = max(ParentRank),
        SuffixListing = max(toint(IsPublicSuffix)),
        HostedListing = max(toint(Hosted))
        by DomainName
    | extend IsHighType = array_length(set_intersect(ThreatTypes, high_types)) > 0
    | extend LastSeenAge = now() - FeedLastSeen
    | extend AlertSeverity = case(
        ParentRank between (1 .. popular_rank) and HostedListing == 0, "Informational",
        IsHighType and LastSeenAge <= recent, "High",
        LastSeenAge <= aging, "Medium",
        "Low")
    | extend ThreatTypeList = strcat_array(ThreatTypes, ", ")
);
let MatchKeys = ActiveThreats | project DomainName;
// A listing that is itself a public suffix (mysynology.net, s3.amazonaws.com) matches only its own name: the hosts under it belong to unrelated parties
let SuffixKeys = ActiveThreats | where SuffixListing == 1 | project DomainName;
let Resolved = DnsByName
    | where Fqdn in (MatchKeys) or Cand2 in (MatchKeys) or Cand3 in (MatchKeys)
    | extend Candidate = set_union(pack_array(Fqdn), pack_array(Cand2, Cand3))
    | mv-expand Candidate to typeof(string)
    | where Candidate in (MatchKeys)
    | where Candidate == Fqdn or Candidate !in (SuffixKeys);
let MatchedNames = Resolved | distinct Fqdn;
// Clients only for the names that matched, joined from the small side: an in() filter fails above 1,000,000
// values, which one domain used for DNS tunnelling can reach
let ClientsByName = MatchedNames
    | join kind=rightsemi DnsRows on Fqdn
    // Windows DNS and most other sources leave SrcHostname empty; the client's IP address stands in for it
    | extend SrcClient = coalesce(column_ifexists("SrcHostname", ""), column_ifexists("SrcIpAddr", ""))
    | summarize
        HostHll = hll_if(SrcClient, isnotempty(SrcClient)),
        SourceIps = make_set(column_ifexists("SrcIpAddr", ""), 20),
        SourceHosts = make_set_if(SrcClient, isnotempty(SrcClient), 20),
        ReportedBy = make_set(column_ifexists("EventProduct", ""), 5)
        by Fqdn;
ActiveThreats
| join kind=inner Resolved on $left.DomainName == $right.Candidate
| join kind=inner ClientsByName on Fqdn
| summarize
    StartTime = min(StartTime),
    EndTime = max(EndTime),
    QueryCount = sum(Queries),
    HostHll = hll_merge(HostHll),
    SampleFqdns = make_set(Fqdn, 10),
    arg_max(Queries, SourceIps, SourceHosts, ReportedBy)
    by DomainName, ThreatTypeList, AlertSeverity, FeedFirstSeen, FeedLastSeen, ParentRank
| extend HostCount = dcount_hll(HostHll)
| extend SourceIp = tostring(SourceIps[0]), SourceHost = tostring(SourceHosts[0])
| project-away HostHll, Queries

let ingestion_delay = 30m;
let rule_lookback = 1h;
let feed_lookback = 14d;
// A domain this rule alerted on is not alerted on again for this long
let dedupe_lookback = 7d;
// Keywords from the shipped list (placeholders) and the customer's own list; SearchKey is the Keyword column.
// Placeholder rows start with "example" and are ignored.
let BrandKeywords = toscalar(
    union
        (_GetWatchlist('WhoisXMLBrandKeywords') | project SearchKey),
        (_GetWatchlist('WhoisXMLBrandKeywordsCustom') | project SearchKey)
    | extend Keyword = tolower(trim(@"\s", tostring(SearchKey)))
    | where strlen(Keyword) >= 4 and Keyword !startswith "example"
    | summarize make_set(Keyword, 200)
);
let Allowlisted = union
    (_GetWatchlist('WhoisXMLDomainAllowlist') | project Domain = tolower(tostring(SearchKey))),
    (_GetWatchlist('WhoisXMLDomainAllowlistCustom') | project Domain = tolower(tostring(SearchKey)));
let AlreadyAlerted = SecurityAlert
    | where TimeGenerated >= ago(dedupe_lookback)
    | where ProviderName == "ASI Scheduled Alerts"
    | extend Details = todynamic(tostring(todynamic(ExtendedProperties)["Custom Details"]))
    | where tostring(Details.WxaRule[0]) == "R6"
    | project Domain = tostring(Details.WxaDomain[0]);
// The hour's lookups, read twice: once for every queried name, then again for the clients of the names that matched
let DnsRows = _Im_Dns(starttime=ago(ingestion_delay + rule_lookback))
    | where isnotempty(DnsQuery)
    | where coalesce(ingestion_time(), TimeGenerated) > ago(rule_lookback)
    | extend Fqdn = tolower(trim_end(@"\.", DnsQuery));
// One row per queried name with only its time span and count, summarised before materialize: per-client detail
// for every name would exhaust the query's memory in estates that query millions of names an hour
let DnsByName = materialize(
    DnsRows
    | summarize
        StartTime = min(TimeGenerated),
        EndTime = max(TimeGenerated),
        Queries = count()
        by Fqdn
    | extend Labels = split(Fqdn, ".")
    | extend LabelCount = array_length(Labels)
    | extend Cand2 = iff(LabelCount >= 2, strcat(tostring(Labels[LabelCount - 2]), ".", tostring(Labels[LabelCount - 1])), "")
    | extend Cand3 = iff(LabelCount >= 3, strcat(tostring(Labels[LabelCount - 3]), ".", Cand2), "")
    | project-away Labels, LabelCount
);
let Candidates = union
    (DnsByName | where isnotempty(Cand2) | distinct Domain = Cand2),
    (DnsByName | where isnotempty(Cand3) | distinct Domain = Cand3)
    | distinct Domain;
let NCand = toscalar(Candidates | count);
let Listed = WhoisXMLTyposquatting_CL
    | where TimeGenerated >= ago(feed_lookback);
let BrandLookalikes = union
        (Listed | where NCand <= 900000 | where DomainName in (Candidates)),
        (Listed | where NCand > 900000 | join kind=leftsemi hint.shufflekey=DomainName (Candidates | project DomainName = Domain) on DomainName)
    | where DomainName !in (AlreadyAlerted)
    // Allowlisted domains drop out through an anti-join from the small side: an in() filter fails above 1,000,000
    // values, which an imported list can reach
    | join kind=leftanti Allowlisted on $left.DomainName == $right.Domain
    | summarize arg_max(FeedDate, GroupNumber, GroupSize, DomainNameUtf) by DomainName
    | extend Keywords = BrandKeywords
    | mv-apply Keyword = Keywords to typeof(string) on (
        where DomainName contains Keyword or DomainNameUtf contains Keyword
        | take 1
    )
    | project DomainName, MatchedKeyword = Keyword, GroupNumber, GroupSize, FeedDate;
let Matched = materialize(
    BrandLookalikes
    | join kind=inner (
        DnsByName
        | extend Candidate = pack_array(Cand2, Cand3)
        | mv-expand Candidate to typeof(string)
        | where isnotempty(Candidate)
    ) on $left.DomainName == $right.Candidate
);
let MatchedNames = Matched | distinct Fqdn;
// Clients only for the names that matched, joined from the small side: an in() filter fails above 1,000,000
// values, which one domain used for DNS tunnelling can reach
let ClientsByName = MatchedNames
    | join kind=rightsemi DnsRows on Fqdn
    // Windows DNS and most other sources leave SrcHostname empty; the client's IP address stands in for it
    | extend SrcClient = coalesce(column_ifexists("SrcHostname", ""), column_ifexists("SrcIpAddr", ""))
    | summarize
        SourceIps = make_set(column_ifexists("SrcIpAddr", ""), 20),
        SourceHosts = make_set_if(SrcClient, isnotempty(SrcClient), 20)
        by Fqdn;
Matched
| join kind=inner ClientsByName on Fqdn
| summarize
    StartTime = min(StartTime),
    EndTime = max(EndTime),
    QueryCount = sum(Queries),
    arg_max(Queries, SourceIps, SourceHosts)
    by DomainName, MatchedKeyword, GroupNumber, GroupSize, FeedDate
| extend SourceIp = tostring(SourceIps[0]), SourceHost = tostring(SourceHosts[0]), WxaRule = "R6"
| project-away Queries

let dns_lookback = 3d;
// Domains whose first row reached this workspace in the last day (TimeGenerated is ingestion time)
let NewlyListed = WhoisXMLNRD_CL
    | where TimeGenerated >= ago(14d)
    | where Reason == "added"
    | summarize ListedInWorkspace = min(TimeGenerated), FeedDate = max(FeedDate) by DomainName
    | where ListedInWorkspace >= ago(1d);
// The look-back's lookups, read twice: once for every queried name, then again for the clients of the names that matched
let DnsRows = _Im_Dns(starttime=ago(dns_lookback))
    | where isnotempty(DnsQuery)
    | extend Fqdn = tolower(trim_end(@"\.", DnsQuery));
// One row per queried name with only its time span and count: per-client detail for every name would exhaust the
// query's memory in estates that query millions of names over the look-back
let Matched = materialize(
    DnsRows
    | summarize
        StartTime = min(TimeGenerated),
        EndTime = max(TimeGenerated),
        QueryCount = count()
        by Fqdn
    | extend Labels = split(Fqdn, ".")
    | extend LabelCount = array_length(Labels)
    | extend Cand2 = iff(LabelCount >= 2, strcat(tostring(Labels[LabelCount - 2]), ".", tostring(Labels[LabelCount - 1])), "")
    | extend Cand3 = iff(LabelCount >= 3, strcat(tostring(Labels[LabelCount - 3]), ".", Cand2), "")
    | extend Candidate = pack_array(Cand2, Cand3)
    | mv-expand Candidate to typeof(string)
    | where isnotempty(Candidate)
    | join kind=inner hint.shufflekey=Candidate (NewlyListed | project Candidate = DomainName, ListedInWorkspace, FeedDate) on Candidate
    // Only lookups that began before the domain reached this workspace: the hourly rule R1 cannot see them
    | where StartTime < ListedInWorkspace
    | project Fqdn, Candidate, StartTime, EndTime, QueryCount, ListedInWorkspace, FeedDate
);
// Clients only for the names that matched, joined from the small side: an in() filter fails above 1,000,000
// values, which one domain used for DNS tunnelling can reach
let ClientsByDomain = Matched
    | distinct Fqdn, Candidate
    | join kind=inner DnsRows on Fqdn
    | extend SrcIp = column_ifexists("SrcIpAddr", "")
    | summarize SourceIps = make_set_if(SrcIp, isnotempty(SrcIp), 20) by Candidate;
// One row per domain: a domain used for DNS tunnelling can carry millions of names
Matched
| summarize
    StartTime = min(StartTime),
    EndTime = max(EndTime),
    QueryCount = sum(QueryCount),
    NameCount = count(),
    SampleFqdns = make_set(Fqdn, 10)
    by Candidate, FeedDate, ListedInWorkspace
| join kind=inner ClientsByDomain on Candidate
// SourceIp is one of the domain's clients, for the IP entity; SampleFqdns are names under the domain, not that client's
| extend SourceIp = tostring(SourceIps[0]), HoursBeforeListedInWorkspace = datetime_diff('hour', ListedInWorkspace, StartTime)
| project StartTime, EndTime, DomainName = Candidate, SampleFqdns, NameCount, FeedDate, ListedInWorkspace,
    HoursBeforeListedInWorkspace, QueryCount, SourceIp, SourceIps
| order by StartTime asc

let lookback = 14d;
// A group counts when at least this many of its domains were resolved in the estate
let min_members_seen = 2;
// The look-back's lookups, read twice: once for every queried name, then again for the clients of the names that matched
let DnsRows = _Im_Dns(starttime=ago(lookback))
    | where isnotempty(DnsQuery)
    | extend Fqdn = tolower(trim_end(@"\.", DnsQuery));
// One row per queried name with only its time span and count: per-client detail for every name would exhaust the
// query's memory in estates that query millions of names over the look-back
let ResolvedDomains = DnsRows
    | summarize
        StartTime = min(TimeGenerated),
        EndTime = max(TimeGenerated),
        QueryCount = count()
        by Fqdn
    | extend Labels = split(Fqdn, ".")
    | extend LabelCount = array_length(Labels)
    | extend Cand2 = iff(LabelCount >= 2, strcat(tostring(Labels[LabelCount - 2]), ".", tostring(Labels[LabelCount - 1])), "")
    | extend Cand3 = iff(LabelCount >= 3, strcat(tostring(Labels[LabelCount - 3]), ".", Cand2), "")
    | extend Candidate = pack_array(Cand2, Cand3)
    | mv-expand Candidate to typeof(string)
    | where isnotempty(Candidate)
    | project Candidate, Fqdn, StartTime, EndTime, QueryCount;
let Members = materialize(
    WhoisXMLTyposquatting_CL
    | where TimeGenerated >= ago(lookback)
    | summarize arg_max(TimeGenerated, GroupSize) by Candidate = DomainName, FeedDate, GroupNumber
);
// Each resolved name under a member once, whatever groups the member is in (a domain can be in several)
let Matched = materialize(
    Members
    | distinct Candidate
    | join kind=inner hint.shufflekey=Candidate ResolvedDomains on Candidate
    | project Candidate, Fqdn, StartTime, EndTime, QueryCount
);
let MatchedNames = Matched | distinct Fqdn;
// Clients only for the names that matched, joined from the small side: an in() filter fails above 1,000,000
// values, which one domain used for DNS tunnelling can reach
let ClientsByName = MatchedNames
    | join kind=rightsemi DnsRows on Fqdn
    | extend SrcIp = column_ifexists("SrcIpAddr", "")
    | summarize SourceIps = make_set_if(SrcIp, isnotempty(SrcIp), 10) by Fqdn
    | project Fqdn, SourceIp = tostring(SourceIps[0]);
// Clients go onto each name before the names are expanded into the groups their domain is in
let MatchedClients = Matched | join kind=inner ClientsByName on Fqdn;
Members
| join kind=inner MatchedClients on Candidate
| summarize
    MembersSeen = dcount(Candidate),
    MembersResolved = make_set(Candidate, 20),
    GroupSize = max(GroupSize),
    StartTime = min(StartTime),
    EndTime = max(EndTime),
    Queries = sum(QueryCount),
    SourceIps = make_set_if(SourceIp, isnotempty(SourceIp), 20)
    by FeedDate, GroupNumber
| where MembersSeen >= min_members_seen
| extend DomainName = tostring(MembersResolved[0]), SourceIp = tostring(SourceIps[0])
| order by MembersSeen desc
